-- talent_affix_def.sql
-- AUTO-GENERATED by build_talent_affixes.ps1 - do not edit directly.
-- Maps:         talent_affixes/_maps.json
-- Spec entries: talent_affixes/<Class>/<spec>.json

CREATE TABLE IF NOT EXISTS `talent_affix_def` (
    `id`             INT UNSIGNED    NOT NULL,
    `name`           VARCHAR(64)     NOT NULL DEFAULT '',
    `class_mask`     INT UNSIGNED    NOT NULL DEFAULT 0,     -- bit (1 << (classId-1)); 0 = any class
    `spec_tree`      TINYINT         NOT NULL DEFAULT -1,    -- -1 = any spec; 0/1/2 = dominant tree
    `max_rank`       TINYINT         NOT NULL DEFAULT 5,     -- talent's max rank in the game
    `spell_family`   TINYINT         NOT NULL DEFAULT 0,     -- SpellFamilyName enum value
    `family_flags0`  INT UNSIGNED    NOT NULL DEFAULT 0,     -- SpellClassOptions.SpellClassMask[0]
    `family_flags1`  INT UNSIGNED    NOT NULL DEFAULT 0,
    `family_flags2`  INT UNSIGNED    NOT NULL DEFAULT 0,
    `carrier_spell`  INT UNSIGNED    NOT NULL DEFAULT 0,     -- a spell from this family
    `spellmod_op`    TINYINT         NOT NULL DEFAULT 0,     -- SpellModOp value
    `spellmod_type`  TINYINT UNSIGNED NOT NULL DEFAULT 107,  -- 107=FLAT  108=PCT
    `value_per_rank` INT             NOT NULL DEFAULT 0,     -- magnitude per rolled rank
    `item_category`  TINYINT UNSIGNED NOT NULL DEFAULT 0,     -- AffixItemCategory: 0=any 8=DAGGER
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Idempotent column addition (servers upgrading without DROP/CREATE)
SET @add_smt = IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS
    WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='talent_affix_def' AND COLUMN_NAME='spellmod_type')=0,
    'ALTER TABLE `talent_affix_def` ADD COLUMN `spellmod_type` TINYINT UNSIGNED NOT NULL DEFAULT 107 AFTER `spellmod_op`',
    'SELECT 1');
PREPARE _s FROM @add_smt; EXECUTE _s; DEALLOCATE PREPARE _s;

SET @add_ic = IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS
    WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='talent_affix_def' AND COLUMN_NAME='item_category')=0,
    'ALTER TABLE `talent_affix_def` ADD COLUMN `item_category` TINYINT UNSIGNED NOT NULL DEFAULT 0',
    'SELECT 1');
PREPARE _s FROM @add_ic; EXECUTE _s; DEALLOCATE PREPARE _s;

